// Background worker: decides which content scripts run on Google, and fetches card definitions for
// them (avoids Google's page CSP/CORS).
// The languages in this download are listed in languages.js (generated by tools/build.js). Their
// content scripts are registered here rather than in the manifest, leaving out languages switched off
// in settings or whose lang/<id>/ folder was deleted, so unused languages cost nothing per search.
"use strict";

importScripts("languages.js");

// ---------- Content scripts ----------

const SCRIPT_ID = "dictionary-box";

// Whether a language's files are all there (someone may have deleted its folder).
async function hasFiles(pack) {
  try {
    for (const f of pack.content) if (!(await fetch(chrome.runtime.getURL(f))).ok) return false;
    return true;
  } catch {
    return false;
  }
}

async function syncContentScripts() {
  const { disabledLangs } = await chrome.storage.sync.get({ disabledLangs: [] });
  const packs = [];
  for (const [id, pack] of Object.entries(LANGUAGE_PACKS)) {
    if (!disabledLangs.includes(id) && (await hasFiles(pack))) packs.push(pack);
  }
  const existing = await chrome.scripting.getRegisteredContentScripts({ ids: [SCRIPT_ID] });
  if (!packs.length) {
    if (existing.length) await chrome.scripting.unregisterContentScripts({ ids: [SCRIPT_ID] });
    return;
  }
  const script = {
    id: SCRIPT_ID,
    js: ["query.js", ...packs.flatMap((p) => p.content), "page.js", "card.js", "content.js"],
    matches: [...new Set(packs.flatMap((p) => p.google))].map((tld) => `https://www.google.${tld}/search*`),
    runAt: "document_start",
  };
  if (existing.length) await chrome.scripting.updateContentScripts([script]);
  else await chrome.scripting.registerContentScripts([script]);
}

// One at a time, so two events can't both try to register the script.
let syncing = Promise.resolve();
const resync = () => (syncing = syncing.then(syncContentScripts).catch((e) => console.error("Dictionary Box:", e)));

// Registrations persist; redo them on install/update/reload (files may have changed), on browser
// start, and when languages are switched on or off.
chrome.runtime.onInstalled.addListener(resync);
chrome.runtime.onStartup.addListener(resync);
chrome.storage.onChanged.addListener((changes, area) => {
  if (area === "sync" && changes.disabledLangs) resync();
});

// ---------- Definitions ----------
// Each language's dictionary lives in lang/<id>/lookup.js and registers itself in LOOKUPS.

const LOOKUPS = {};

for (const pack of Object.values(LANGUAGE_PACKS)) {
  if (!pack.lookup) continue;
  try {
    importScripts(pack.lookup);
  } catch {
    // Folder deleted: that language just isn't available.
  }
}

const cache = new Map();

async function lookup(word, lang) {
  const key = `${lang}:${word.toLowerCase()}`;
  if (cache.has(key)) return cache.get(key);
  if (!LOOKUPS[lang]) return { error: `no dictionary for “${lang}”` };
  const result = await LOOKUPS[lang](word);
  if (cache.size > 200) cache.clear();
  cache.set(key, result);
  return result;
}

chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
  if (msg && msg.type === "gdb-lookup" && typeof msg.word === "string" && typeof msg.lang === "string") {
    lookup(msg.word, msg.lang)
      .then(sendResponse)
      .catch((err) => sendResponse({ error: String((err && err.message) || err) }));
    return true; // keep channel open for async response
  }
});
